"use client";

import {
  Children,
  type HTMLAttributes,
  type KeyboardEvent,
  type PointerEvent,
  type ReactElement,
  type ReactNode,
  isValidElement,
  useId,
  useRef,
  useState,
} from "react";
import { clamp } from "../utils/motion";
import { cx } from "../utils/cx";

export type SplitterProps = Omit<HTMLAttributes<HTMLDivElement>, "onChange"> & {
  direction?: "horizontal" | "vertical";
  /** Starting sizes in percent, one per panel. Default: equal. */
  defaultSizes?: number[];
  /** Controlled sizes in percent. */
  sizes?: number[];
  onSizesChange?: (sizes: number[]) => void;
  /** Smallest size of any panel, percent. Default 10. */
  minSize?: number;
  /** Panels (`SplitterPanel`). Draggable handles are placed between them. */
  children: ReactNode;
};

export type SplitterPanelProps = HTMLAttributes<HTMLDivElement>;
export function SplitterPanel({ className, ...rest }: SplitterPanelProps) {
  return <div {...rest} className={cx("hm-splitter-panel", className)} />;
}

/**
 * Resizable panels. Each handle is a focusable `role="separator"`: drag it, or use the arrow keys (Shift for bigger
 * steps), Home and End. Sizes are percentages and the layout follows the pointer with no easing, so dragging never lags.
 */
export function Splitter({
  direction = "horizontal",
  defaultSizes,
  sizes: controlled,
  onSizesChange,
  minSize = 10,
  className,
  style,
  children,
  ...rest
}: SplitterProps) {
  const panels = Children.toArray(children).filter(isValidElement) as ReactElement<SplitterPanelProps>[];
  const n = panels.length;
  const [inner, setInner] = useState(() =>
    defaultSizes && defaultSizes.length === n ? defaultSizes : Array(n).fill(100 / n),
  );
  const sizes = controlled ?? inner;
  const root = useRef<HTMLDivElement>(null);
  const base = useId();
  const horizontal = direction === "horizontal";

  const commit = (next: number[]) => {
    if (controlled === undefined) setInner(next);
    onSizesChange?.(next);
  };
  /** Move the boundary after panel `i` by `delta` percent, taking from one side and giving to the other. */
  const move = (i: number, delta: number, from = sizes) => {
    const a = from[i] ?? 0;
    const b = from[i + 1] ?? 0;
    const total = a + b;
    const na = clamp(a + delta, minSize, total - minSize);
    const next = [...from];
    next[i] = na;
    next[i + 1] = total - na;
    commit(next);
  };
  const drag = useRef<{ start: number; from: number[]; size: number } | null>(null);
  const down = (e: PointerEvent<HTMLDivElement>) => {
    const r = root.current?.getBoundingClientRect();
    if (!r) return;
    drag.current = { start: horizontal ? e.clientX : e.clientY, from: sizes, size: horizontal ? r.width : r.height };
    e.currentTarget.setPointerCapture(e.pointerId);
    e.currentTarget.dataset.dragging = "";
  };
  const movePtr = (i: number) => (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) return;
    move(i, (((horizontal ? e.clientX : e.clientY) - d.start) / d.size) * 100, d.from);
  };
  const up = (e: PointerEvent<HTMLDivElement>) => {
    drag.current = null;
    delete e.currentTarget.dataset.dragging;
  };
  const key = (i: number) => (e: KeyboardEvent<HTMLDivElement>) => {
    const big = e.shiftKey ? 10 : 2;
    const dec = horizontal ? "ArrowLeft" : "ArrowUp";
    const inc = horizontal ? "ArrowRight" : "ArrowDown";
    if (e.key === dec) move(i, -big);
    else if (e.key === inc) move(i, big);
    else if (e.key === "Home") move(i, -100);
    else if (e.key === "End") move(i, 100);
    else return;
    e.preventDefault();
  };

  return (
    <div {...rest} ref={root} className={cx("hm-splitter", className)} data-direction={direction} style={style}>
      {panels.map((panel, i) => (
        <div key={panel.key ?? i} className="hm-splitter-cell" style={{ flexGrow: sizes[i], flexBasis: 0 }}>
          {panel}
          {i < n - 1 ? (
            <div
              role="separator"
              tabIndex={0}
              id={`${base}-${i}`}
              aria-orientation={horizontal ? "vertical" : "horizontal"}
              aria-valuenow={Math.round(sizes[i] ?? 0)}
              aria-valuemin={minSize}
              aria-valuemax={100 - minSize}
              aria-label={`Resize panels ${i + 1} and ${i + 2}`}
              className="hm-splitter-handle"
              onPointerDown={down}
              onPointerMove={movePtr(i)}
              onPointerUp={up}
              onPointerCancel={up}
              onKeyDown={key(i)}
            />
          ) : null}
        </div>
      ))}
    </div>
  );
}
